class InputCell:
    def __init__(self, initial_value):
        self._value = initial_value
        self._observers = []

    @property
    def value(self):
        return self._value

    @value.setter
    def value(self, new_value):
        self._value = new_value
        # Collect all compute cells that transitively depend on this input.
        affected = []
        seen = set()
        stack = list(self._observers)
        while stack:
            cell = stack.pop()
            if id(cell) in seen:
                continue
            seen.add(id(cell))
            affected.append(cell)
            stack.extend(cell._observers)
        # `affected` is in dependency order (dependencies before dependents),
        # so recomputing in this order reaches a stable state.
        for cell in affected:
            cell._recompute()


class ComputeCell:
    def __init__(self, inputs, compute_function):
        self._inputs = inputs
        self._compute_function = compute_function
        self._observers = []
        self._callbacks = []
        self.value = None
        for input_cell in inputs:
            input_cell._observers.append(self)
        self._recompute()

    def _recompute(self):
        new_value = self._compute_function([cell.value for cell in self._inputs])
        if new_value != self.value:
            self.value = new_value
            for callback in self._callbacks:
                callback(self.value)

    def add_callback(self, callback):
        self._callbacks.append(callback)

    def remove_callback(self, callback):
        if callback in self._callbacks:
            self._callbacks.remove(callback)

